    confusion: /\b(no entendi|como|que pedo|explica)\b/i
};

/* ======================================================================================
   TELEMETRY
====================================================================================== */

function emitSemanticTelemetry(

    type,
    payload = {},
    severity = "INFO"

) {

    const event = {

        type,
        payload,
        severity,
        timestamp: Date.now()
    };

    console.log(

        `%c🧠 [SEMANTIC:${type}]`,
        "color:#67e8f9;font-weight:bold;",
        payload
    );

    window.__SEMANTIC_COGNITIVE_MATRIX__
        .semanticTelemetry
        .push(event);

    window.dispatchEvent(

        new CustomEvent(
            "semantic-cognitive-event",
            {
                detail: event
            }
        )
    );
}

/* ======================================================================================
   NORMALIZATION
====================================================================================== */

function normalize(text = "") {

    return String(text)
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^\w\s]/g, "")
        .trim();
}

/* ======================================================================================
   TOKENIZATION
====================================================================================== */

function tokenize(text = "") {

    return normalize(text)
        .split(/\s+/)
        .filter(Boolean)
        .filter(w =>
            !STOPWORDS.has(w)
        );
}

/* ======================================================================================
   FUZZY SEMANTIC DETECTION
====================================================================================== */

function detectFuzzyMeaning(tokens = []) {

    const meanings = [];

    Object.entries(CONCEPT_CLUSTERS)
        .forEach(([concept, words]) => {

            let score = 0;

            tokens.forEach(token => {

                if (
                    words.includes(token)
                ) {

                    score++;
                }
            });

            if (score > 0) {

                meanings.push({

                    concept,
                    score
                });
            }
        });
